    },
    {
      "muscleGroup": "Shoulders",
      "severity": "mild",
      "observation": "Shoulders account for only 10.4% of volume with 4 sets and a stalled strength index. Given the user's muscle-building goal, the shoulders are likely undertrained relative to the chest (26.8%) and back (28%), which could limit long-term pressing and pulling balance."
    }
  ],
  "deloadRecommended": false,
